<?php
declare(strict_types=1); namespace TmsAi\Core;
final class Auth { public static function hasAdmin():bool{return (int)App::db()->querySingle('SELECT COUNT(*) FROM admins')>0;} public static function loggedIn():bool{return !empty($_SESSION['admin_id']);} public static function requireAdmin():void{if(!self::loggedIn()){header('Location: /login');exit;}}
public static function setup(string $u,string $p):bool{if(self::hasAdmin()||strlen($u)<3||strlen($p)<8)return false;$s=App::db()->prepare('INSERT INTO admins(username,password_hash,created_at) VALUES(:u,:p,:t)');$s->bindValue(':u',$u,SQLITE3_TEXT);$s->bindValue(':p',password_hash($p,PASSWORD_DEFAULT),SQLITE3_TEXT);$s->bindValue(':t',time(),SQLITE3_INTEGER);return(bool)$s->execute();}
public static function login(string $u,string $p):bool{$s=App::db()->prepare('SELECT id,password_hash FROM admins WHERE username=:u LIMIT 1');$s->bindValue(':u',$u,SQLITE3_TEXT);$r=$s->execute()?->fetchArray(SQLITE3_ASSOC);if(!$r||!password_verify($p,$r['password_hash']))return false;session_regenerate_id(true);$_SESSION['admin_id']=(int)$r['id'];return true;}
public static function logout():void{$_SESSION=[];session_destroy();}
public static function bearer():string{$h=$_SERVER['HTTP_AUTHORIZATION']??'';return preg_match('/^Bearer\s+(.+)$/i',trim($h),$m)?trim($m[1]):'';}
public static function requireClientKey():array{$plain=self::bearer();if($plain==='')App::json(['error'=>['message'=>'Missing API key.','type'=>'authentication_error']],401);$s=App::db()->prepare('SELECT * FROM client_keys WHERE key_hash=:h AND enabled=1 LIMIT 1');$s->bindValue(':h',hash('sha256',$plain),SQLITE3_TEXT);$r=$s->execute()?->fetchArray(SQLITE3_ASSOC);if(!$r)App::json(['error'=>['message'=>'Invalid API key.','type'=>'authentication_error']],401);App::db()->exec('UPDATE client_keys SET last_used_at='.time().' WHERE id='.(int)$r['id']);return $r;}}
